import sys, ezdxf
for p in sys.argv[1:]:
    print("=====", p.split("\\")[-1])
    d = ezdxf.readfile(p)
    for e in d.modelspace():
        t = e.dxftype()
        if t == "LINE":
            print(t, e.dxf.layer, tuple(round(v, 3) for v in e.dxf.start[:2]), tuple(round(v, 3) for v in e.dxf.end[:2]))
        elif t == "ARC":
            print(t, e.dxf.layer, tuple(round(v, 3) for v in e.dxf.center[:2]), "R", round(e.dxf.radius, 3), round(e.dxf.start_angle, 1), round(e.dxf.end_angle, 1))
        elif t == "CIRCLE":
            print(t, e.dxf.layer, tuple(round(v, 3) for v in e.dxf.center[:2]), "R", round(e.dxf.radius, 3))
        else:
            print(t, e.dxf.layer)

